INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64685337', 64685337, 'analyze_legacy', 'Kab. Musi Rawas', 'kabkota', 'Dinas Kebudayaan dan Pariwisata', 'Jasa Tenaga Kebersihan/ Petugas Kebersihan Luar Gedung  (Danau Aur) - 02', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sumatera Selatan, Musi Rawas (Kab.)', 11110000, 'January 2026', 'APBD', 1, 1, '1 paket', 'a) Menyapu, mengepel, dan membersihkan area-area publik seperti aula, gazebo dan tempat istirahat; b) Membersihkan fasilitas umum (tempat sampah, papan informasi, area makan, dll); c) Menyapu halaman, jalan setapak/pedestrian, taman, dan selokan; d) Mengumpulkan dan memilah dan membuang sampah ke tempat pembuangan sementara (TPS) atau bak penampungan yang disediakan; e) Membersihkan bak sampah, tempat pembuangan sementara (TPS), serta memastikan terangkut ke Dinas Kebersihan; f) Merawat kebersihan area pagar, dinding luar, dan selasar; g) Membersihkan saluran air agar tidak tersumbat; h) Melakukan perawatan ringan terhadap peralatan kebersihan (sapu, tong sampah, gerobak, dan sebagainya); i) Menjaga ketersediaan perelngkapan kebersihan seperti sabun, cairan pembersihan, kantong plastik, dan alat pelindung diri; j) Melaporkan kondisi kerusakan fasilitas umum, saluran tersumbat, atau potensi gangguan kebersihan lainnya kepada instansi terkait; k) Membantu menjaga suasana tertib, sopan dan ramah terhadap pengunjung; l) Mengisi laporan kegiatan harian kebersihan dan menyerahkan kepada', 'a) Warga Negara Indonesia (WNI); b) Usia 18–58 tahun; c) Sehat jasmani dan rohani; d) Pendidikan minimal SD/ SLTP/ SLTA (apabila tidak memliki Ijazah dibuktikan dengan pengalaman pekerjaan minimal 1 tahun); e) Berkelakuan baik; f) Disiplin, tanggungjawab, jujur, dan mampu bekerja dalam tim; g) Mampu berkomunikasi dengan baik dan sopan terhadap pengunjung; h) Bersedia bekerja pada hari libur nasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1720047);
