INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64746262', 64746262, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Direktorat Jenderal Ekosistem Digital', 'Pengadaan Jasa Konsultansi Penyusunan Pengukuran Indikator Persentase Tingkat Produktivitas Adopsi Teknologi Baru', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 400000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Untuk mencapai maksud dan tujuan pekerjaan ini maka dilakukan: a. Tahap Persiapan dan Pengembangan Metodologi 1)Melakukan Studi Literatur dan Telaah Regulasi melalui mekanisme benchmark pengukuran dampak produktivitas digital, adopsi teknologi digital paling sedikit AI, IoT, Blockchain, serta inovasi digital berbasis greentech. 2)Melakukan review terhadap framework pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech pada Renstra Komdigi 2025-2029 dan hasil pengukuran tahun 2025. 3)Memberikan rekomendasi terkait alternatif formula termasuk Indikator dan sub-indikator pengukuran perhitungan tingkat produktivitas, persentase pertumbuhan adopsi digital, persentase pertumbuhan inovasi digital berbasis greentech Berdasarkan hasil review. 4)Menentukan metodologi pengumpulan data primer dan target responden yang mencakup pelaku usaha paling sedikit yang memanfaatkan teknologi AI, IoT, Blockchain dan greentech. 5)Melakukan pengumpulan data pelaku usaha paling sedikit yang memanfaatkan teknologi AI, IoT, Blockchain dan greentech. 6)Menyusun instrumen daftar pertanyaan kuesioner dalam rangka pelaksanaan pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech. 7)Menentukan metode analisis pengukuran hasil survei tingkat produktivitas, pengukuran persentase pertumbuhan adopsi digital, pengukuran persentase pertumbuhan inovasi digital berbasis greentech b. Tahap Pengumpulan Data 1)Melaksanakan pengumpulan data primer melalui mekanisme survei pengukuran tingkat produktivitas, pengukuran persentase pertumbuhan adopsi digital, pengukuran persentase pertumbuhan inovasi digital berbasis greentech. 2)Menyelenggarakan diskusi mendalam dengan para akademisi, pelaku usaha, asosiasi, dan penyedia teknologi. c. Tahap Pengolahan Data dan analisis data 1)Melakukan validasi data dari pelaksanaan survei pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech. 2)Melakukan pengolahan, pengujian dan perhitungan data berdasarkan hasil survei menggunakan formula. 3)Melakukan Analisis dengan menggunakan metode pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech. 4)Merumuskan hasil survei pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech d. Tahap Perumusan Rekomendasi dan Pelaporan 1)Merumuskan langkah-langkah rekomendasi dan rencana aksi. Menyusun laporan akhir dalam bentuk laporan lengkap, policy brief, paparan presentasi.', 'Untuk mencapai maksud dan tujuan pekerjaan ini maka dilakukan: a. Tahap Persiapan dan Pengembangan Metodologi 1)Melakukan Studi Literatur dan Telaah Regulasi melalui mekanisme benchmark pengukuran dampak produktivitas digital, adopsi teknologi digital paling sedikit AI, IoT, Blockchain, serta inovasi digital berbasis greentech. 2)Melakukan review terhadap framework pengukuran persentase tingkat produktivitas, pertumbuhan adopsi digital, pertumbuhan inovasi digital berbasis greentech pada Renstra Komdigi 2025-2029 dan hasil 