INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64747026', 64747026, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyusunan Pedoman Teknik Analisis Rencana Tata Ruang', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 999444000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Berdasarkan pasal 8 ayat 5 Undang - Undang Nomor 26 Tahun 2007 tentang Penataan Ruang (UU 26/2007), disebutkan bahwa dalam rangka penyelenggaraan penataan ruang, Pemerintah berwenang menyusun dan menetapkan pedoman bidang penataan ruang. Pedoman bidang penataan ruang yang dimaksud mencakup norma, standar, dan manual dalam bidang penataan ruang. Berdasarkan hal-hal tersebut, maka penyusunan Pedoman Teknik Analisis Penyusunan Rencana Tata Ruang menjadi suatu keharusan guna: a. Menyesuaikan dengan sistem hukum dan kebijakan terbaru; b. Menyediakan panduan teknis yang akurat, aplikatif, dan berbasis data spasial digital; c. Menyediakan metodologi analisis yang terintegrasi secara spasial, sektoral, dan vertikal (darat–laut–udara–dalam bumi); d. Mendukung keterpaduan antara RTR dengan KLHS; dan e. Mendorong perencanaan tata ruang yang terukur, responsif, dan berorientasi pada hasil.', 'Keluaran: 1. Materi Teknis Pedoman Teknik Analisis Penyusunan Rencana Tata Ruang 2. Rancangan Draft Peraturan Menteri tentang Pedoman Teknik Analisis Penyusunan Rencana Tata Ruang beserta lampirannya 3. Selain dokumen tersebut, kegiatan ini juga menghasilkan dokumen laporan yang terdiri dari: a. Laporan Pendahuluan Laporan ini sekurang-kurangnya berisi metoda pelaksanaan masing-masing aktivitas yang tercakup dalam ruang lingkup kegiatan, jadwal pelaksanaan kegiatan secara lebih terinci, Surat Keputusan tentang Pembentukan Tim Kontraktual, dan agenda pelaksanaan pekerjaan. b. Laporan Antara Laporan ini ekurang-kurangnya memuat kemajuan pelaksanaan kegiatan pada periode tertentu yang membahas tentang kinerja, progres, dan pemenuhan kewajiban kontraktual. c. Laporan Bulanan Laporan ini memuat kemajuan pekerjaan dan hasil setiap pembahasan yang dilakukan pada bulan tersebut. d. Laporan Akhir Laporan ini memuat rangkuman dan hasil-hasil kegiatan selama Tahun Anggaran 2026 disertai dengan review dan evaluasi pelaksanaannya (dalam ruang lingkup yang sesuai dengan tugas-tugas kesekretariatan). e. Buku Executive Summary Hasil Kajian (Deluxe), yang berisi rangkuman seluruh laporan kegiatan serta lesson learned yang disusun dalam format penyajian buku secara deluxe.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1723884);
