INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64788690', 64788690, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN MANAJEMEN PROGRAM DAN KEGIATAN PIMPINAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 78545456, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '8', 'Posisi Jasa Konsultasi Manajemen Program dan Kegiatan Pimpinan di Sekretariat Transformasi Ekonomi Indonesia Tahun 2026 memiliki Ruang Lingkup sebagai berikut: Inventarisasi dan pengumpulan data kegiatan untuk memudahkan mengidentifikasi seluruh program dan kegiatan yang dilaksanakan oleh unit-unit kerja di lingkungan Deputi PMP, termasuk jadwal pelaksanaan, target kinerja, dan anggaran yang digunakan. Penyusunan sistem pelacakan dan pemantauan kegiatan (tracking system) dengan merancang alat bantu (format pelaporan, matriks logframe, dashboard sederhana, dll.) untuk memastikan kegiatan berjalan sesuai rencana dan target yang ditetapkan. Dokumentasi pelaksanaan kegiatan dengan merekam hasil rapat, koordinasi, pelaksanaan kegiatan, serta menyusun dokumentasi administratif seperti daftar hadir, TOR, notula, dan laporan hasil kegiatan. Analisis kinerja dan capaian program dengan melakukan penilaian terhadap efektivitas dan efisiensi pelaksanaan kegiatan, mengidentifikasi kendala dan memberikan alternatif solusi berbasis data. Penyusunan laporan manajemen program dan kegiatan secara berkala dalam format bulanan, triwulanan, dan tahunan yang berisi informasi substantif, perkembangan kinerja, dan rekomendasi kebijakan. Fasilitasi koordinasi dan sinkronisasi kegiatan lintas unit dalam rangka mendukung proses komunikasi dan kolaborasi antar direktorat dan sekretariat untuk memastikan keterpaduan pelaksanaan kegiatan dan pemanfaatan sumber daya secara optimal.', 'Pendidikan konsultan minimal S1 bidang ekonomi, komunikasi atau hubungan internasional atau sejenisnya baik di dalam ataupun di luar negeri dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; Memiliki pengalaman baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dan dapat dibuktikan dengan surat kontrak dan atau surat pengalaman; Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1729035);
